export function slugify(title) {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

export function uniqueSlug(title, taken) {
  const base = slugify(title) || 'untitled';
  let slug = base;
  for (let n = 2; taken.has(slug); n += 1) slug = base + '-' + n;
  taken.add(slug);
  return slug;
}
